import os
import sys
import json
import time
from datetime import datetime

NOTES_FILE = "notes.dat"
LOG_FILE = "notes.log"

def compute_tag(key, id, text, created_at):
    data = f"{key}{id}{text}{created_at}".encode('utf-8')
    return hex(int.from_bytes(data, byteorder='big') & 0xFFFFFFFF)

def load_notes():
    if not os.path.exists(NOTES_FILE):
        return []
    with open(NOTES_FILE, 'r') as f:
        return json.load(f)

def save_notes(notes):
    with open(NOTES_FILE, 'w') as f:
        json.dump(notes, f)

def log_message(action, id, message=None):
    timestamp = datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')
    log_entry = f"{timestamp} OK {action} {id}" if message is None else f"{timestamp} ERROR {action} {id} {message}"
    with open(LOG_FILE, 'a') as f:
        f.write(log_entry + '\n')

def add_note(key, id, text):
    notes = load_notes()
    created_at = datetime.utcnow().strftime('%Y-%m-%dT%H:MM:SSZ')
    tag = compute_tag(key, id, text, created_at)

    note = {
        'id': id,
        'text': text,
        'created_at': created_at,
        'tag': tag
    }

    if id in [n['id'] for n in notes]:
        notes = [n for n in notes if n['id'] != id]
        notes.append(note)
    else:
        notes.append(note)

    save_notes(notes)
    log_message('add', id)
    print(f"added {id}")
    sys.exit(0)

def get_note(key, id):
    notes = load_notes()
    for note in notes:
        if note['id'] == id:
            computed_tag = compute_tag(key, note['id'], note['text'], note['created_at'])
            if computed_tag == note['tag']:
                print(note['text'])
                log_message('get', id)
                sys.exit(0)
            else:
                log_message('get', id, "tag mismatch")
                sys.exit(2)
    log_message('get', id, "not found")
    sys.exit(1)

def main():
    if len(sys.argv) < 2:
        print("Usage: python notes_store.py <add|get> <id> <text>")
        sys.exit(1)

    action = sys.argv[1]
    if action not in ('add', 'get'):
        print("Invalid action. Use 'add' or 'get'.")
        sys.exit(1)

    if action == 'add' and len(sys.argv) < 4:
        print("Usage: python notes_store.py add <id> <text>")
        sys.exit(1)

    key = os.getenv('NOTES_KEY')
    if not key:
        print("Error: NOTES_KEY environment variable not set.")
        sys.exit(1)

    if action == 'add':
        if len(sys.argv) < 4:
            print("Usage: python notes_store.py add <id> <text>")
            sys.exit(1)
        id = sys.argv[2]
        text = ' '.join(sys.argv[3:])
        add_note(key, id, text)
    elif action == 'get':
        if len(sys.argv) < 3:
            print("Usage: python notes_store.py get <id>")
            sys.exit(1)
        id = sys.argv[2]
        get_note(key, id)

if __name__ == "__main__":
    main()

import os
import sys
import json
import time
from datetime import datetime, timezone

def compute_tag(note_id, text, created_at, key):
    combined = f"{note_id}{text}{created_at}{key}".encode('utf-8')
    return hex(int.from_bytes(combined, byteorder='big') & 0xFFFFFFFF)[2:].zfill(8)

def load_notes():
    if os.path.exists('notes.dat'):
        with open('notes.dat', 'r') as f:
            return json.load(f)
    return {}

def save_notes(notes):
    with open('notes.dat', 'w') as f:
        json.dump(notes, f)

def log_entry(action, id, message=None):
    entry = f"OK {action} {id}" if message is None else f"ERROR {action} {id} {message}"
    with open('notes.log', 'a') as f:
        f.write(entry + '\n')

def main():
    if len(sys.argv) < 2:
        print("Usage: python notes_store.py add <id> <text> or python notes_store.py get <id>")
        sys.exit(1)

    action = sys.argv[1]
    if action == 'add' and len(sys.argv) < 4:
        print("Usage: python notes_store.py add <id> <text>")
        sys.exit(1)
    elif action == 'get' and len(sys.argv) < 3:
        print("Usage: python notes_store.py get <id>")
        sys.exit(1)

    notes = load_notes()
    key = os.getenv('NOTES_KEY')
    if not key:
        print("Error: NOTES_KEY environment variable not set")
        log_entry(action, sys.argv[2] if len(sys.argv) > 2 else sys.argv[1], "NOTES_KEY not set")
        sys.exit(1)

    if action == 'add':
        if len(sys.argv) < 4:
            sys.exit(1)
        note_id = sys.argv[2]
        text = ' '.join(sys.argv[3:])
        created_at = datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
        tag = compute_tag(note_id, text, created_at, key)

        if note_id in notes:
            notes[note_id] = {
                'id': note_id,
                'text': text,
                'created_at': created_at,
                'tag': tag
            }
        else:
            notes[note_id] = {
                'id': note_id,
                'text': text,
                'created_at': created_at,
                'tag': tag
            }

        save_notes(notes)
        print(f"added {note_id}")
        log_entry(action, note_id)
        sys.exit(0)

    elif action == 'get':
        if len(sys.argv) < 3:
            sys.exit(1)
        note_id = sys.argv[2]

        if note_id not in notes:
            print("not found")
            log_entry(action, note_id, "Note not found")
            sys.exit(1)

        stored_note = notes[note_id]
        recomputed_tag = compute_tag(stored_note['id'], stored_note['text'], stored_note['created_at'], key)

        if recomputed_tag != stored_note['tag']:
            print("invalid")
            log_entry(action, note_id, "Tag mismatch")
            sys.exit(2)

        print(stored_note['text'])
        log_entry(action, note_id)
        sys.exit(0)

if __name__ == "__main__":
    main()

import argparse
import base64
import hashlib
import json
import os
import sys
from datetime import datetime, timezone

def compute_tag(note, key):
    data = f"{note['id']}{note['text']}{note['created_at']}".encode()
    h = hashlib.sha256(data)
    h.update(key.encode())
    return base64.urlsafe_b64encode(h.digest()).decode().rstrip('=')

def load_notes():
    if os.path.exists('notes.dat'):
        with open('notes.dat', 'r') as f:
            return json.load(f)
    return {}

def save_notes(notes):
    with open('notes.dat', 'w') as f:
        json.dump(notes, f)

def log_action(action, id, message=None):
    log_entry = f"OK {action} {id}" if message is None else f"ERROR {action} {id} {message}"
    with open('notes.log', 'a') as f:
        f.write(log_entry + '\n')

def add_note(id, text):
    notes = load_notes()
    created_at = datetime.now(timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
    note = {
        'id': id,
        'text': text,
        'created_at': created_at,
        'tag': compute_tag({'id': id, 'text': text, 'created_at': created_at}, os.getenv('NOTES_KEY'))
    }
    if id in notes:
        notes[id] = note
    else:
        notes[id] = note
    save_notes(notes)
    log_action('add', id)
    print(f"added {id}")
    sys.exit(0)

def get_note(id):
    notes = load_notes()
    if id not in notes:
        log_action('get', id, 'not found')
        print('not found')
        sys.exit(1)
    note = notes[id]
    computed_tag = compute_tag(note, os.getenv('NOTES_KEY'))
    if computed_tag != note['tag']:
        log_action('get', id, 'invalid')
        print('invalid')
        sys.exit(2)
    print(note['text'])
    sys.exit(0)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('action', choices=['add', 'get'])
    parser.add_argument('id', type=str)
    parser.add_argument('text', nargs='?', type=str)
    args = parser.parse_args()

    if args.action == 'add':
        if args.text is None:
            parser.error('text is required for add')
        add_note(args.id, args.text)
    elif args.action == 'get':
        get_note(args.id)

if __name__ == '__main__':
    main()
